struct NonVirtual {
    void doWork() {} // Direct call, can be inlined
};

struct Virtual {
    virtual void doWork() {} // Requires vptr and vtable
};

int main() {
    NonVirtual n;
    Virtual v;

    // sizeof(n) is 1 byte (empty structs are 1 byte in C++)
    // sizeof(v) is 8 bytes (because it contains a hidden 64-bit vptr)
}
